package com.ruoyi.framework.shiro.realm;

import com.ruoyi.common.core.domain.entity.SysUser;
import com.ruoyi.system.service.ISysUserService;
import org.apache.shiro.authc.*;                     // AuthenticationToken / SimpleAuthenticationInfo 等
import org.apache.shiro.authz.AuthorizationInfo;
import org.apache.shiro.authz.SimpleAuthorizationInfo;
import org.apache.shiro.realm.AuthorizingRealm;      // Realm 基类：认证+授权两个回调
import org.apache.shiro.subject.PrincipalCollection;
import java.util.Set;
import java.util.stream.Collectors;

// ══ Shiro 版「认证 + 授权」的落点：两个回调方法就是全部 ══
public class UserRealm extends AuthorizingRealm {

    private final ISysUserService userService;

    public UserRealm(ISysUserService userService) {
        this.userService = userService;
    }

    /**
     * 认证回调（你是谁）：登录时触发。
     * 职责：查库 → 状态校验 → 把数据库密文交给 CredentialsMatcher 比对。
     * 注意：Realm 自己不比对密码！
     */
    @Override
    protected AuthenticationInfo doGetAuthenticationInfo(AuthenticationToken token) {
        String username = (String) token.getPrincipal();       // 登录表单里的用户名
        SysUser user = userService.selectUserByUserName(username);
        if (user == null) {
            throw new UnknownAccountException("用户不存在");
        }
        // 把用户(Principal)与密文交给框架，匹配器用明文重算后 equals
        return new SimpleAuthenticationInfo(user, user.getPassword(), getName());
    }

    /**
     * 授权回调（你能干什么）：首次权限校验时触发。
     * 职责：收集角色键（roleKey）与权限字符串（perms）两个集合。
     */
    @Override
    protected AuthorizationInfo doGetAuthorizationInfo(PrincipalCollection principals) {
        SysUser user = (SysUser) principals.getPrimaryPrincipal();   // 认证回调存入的 Principal
        SimpleAuthorizationInfo info = new SimpleAuthorizationInfo();

        // 角色键集合：对应 @RequiresRoles / hasRole 校验
        info.setRoles(user.getRoles() == null
            ? Set.of()
            : user.getRoles().stream().map(r -> r.getRoleKey()).collect(Collectors.toSet()));

        // 权限字符串集合：对应 @RequiresPermissions / hasPermi 校验
        info.setStringPermissions(user.getPermissions());
        return info;
    }
}

package com.ruoyi.framework.web.service;

import com.ruoyi.common.core.domain.entity.SysUser;
import com.ruoyi.common.core.domain.model.LoginUser;
import com.ruoyi.common.exception.ServiceException;
import com.ruoyi.system.service.ISysUserService;
import org.springframework.security.core.userdetails.UserDetails;
import org.springframework.security.core.userdetails.UserDetailsService;
import org.springframework.stereotype.Service;

@Service
public class UserDetailsServiceImpl implements UserDetailsService {

    private final ISysUserService userService;
    private final SysPasswordService passwordService;

    public UserDetailsServiceImpl(ISysUserService userService, SysPasswordService passwordService) {
        this.userService = userService;
        this.passwordService = passwordService;
    }

    @Override
    public UserDetails loadUserByUsername(String username) {
        SysUser user = userService.selectUserByUserName(username);
        if (user == null) {
            throw new ServiceException("用户不存在");
        }
        passwordService.validate(user);   // 锁定/密码错误次数校验
        // LoginUser 实现 UserDetails：用户 + 权限集合一起返回
        return new LoginUser(user.getUserId(), user.getDeptId(), user, user.getPermissions());
    }
}
